	public static object Parse(System.Type t, string s)
	{
		IDictionary d = Json.Deserialize(s) as IDictionary;
		return Parse(t, d);
	}

	public static T Parse<T>(string s)
	{
		System.Type typeFromHandle = typeof(T);
		return (T)Convert.ChangeType(Parse(typeFromHandle, s), typeFromHandle);
	}

	public static T Parse<T>(IDictionary d)
	{
