	public static string EncodeJsonString<T>(T o)
	{
		if (o == null)
		{
			return null;
		}
		return Json.Serialize(EncodeJsonObject(o));
	}

	public static Dictionary<string, object> EncodeJsonObject<T>(T o)
	{
		if (o == null)
		{
			return null;
		}
		System.Type type = o.GetType();
		Func<object, Dictionary<string, object>> value = null;
		if (_encoder.TryGetValue(type, out value) && value != null)
		{
			return value(o);
		}
		return null;
	}
